        val n=amount.size;
        this.amount=amount;
        graph=Array(n){
            mutableListOf()
        };
        for(edge in edges){
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0])
        };
        val parent=IntArray(n){
            -2
        };
        val depth=IntArray(n);
        parent[0]=-1;
        val queue=java.util.ArrayDeque<Int>();
        queue.offer(0);
        while(queue.isNotEmpty()){
            val node=queue.poll();
            for(next in graph[node])if(parent[next]==-2){
                parent[next]=node;
                depth[next]=depth[node]+1;
                queue.offer(next)
            }
        };
        var node=bob;
        var time=0;
        while(node!=-1){
            if(time<depth[node])amount[node]=0 else if(time==depth[node])amount[node]/=2;
            node=parent[node];
            time++
        };
        return path(0,-1)
    }
